import{_ as t,o as r,c as o,l as n,t as a,N as s}from"./chunks/framework.Gjrf2Eoj.js";const b=JSON.parse('{"title":"mv | x-cmd man (man1) | move (rename) files","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | mv - move (rename) files","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"mv | x-cmd man (man1) | move (rename) files"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | mv - move (rename) files"}]]},"headers":[],"params":{"isMan":true,"man":"mv","category":"man1","desc":"move (rename) files"},"relativePath":"man1/mv.md","filePath":"man1/mv.md"}'),d={name:"man1/mv.md"},i={class:"visually-hidden"},l=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>mv - move (rename) files</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>mv</strong> [<em>OPTION</em>]... [<em>-T</em>] <em>SOURCE DEST</em> <br> <strong>mv</strong> [<em>OPTION</em>]... <em>SOURCE</em>... <em>DIRECTORY</em> <br> <strong>mv</strong> [<em>OPTION</em>]... <em>-t DIRECTORY SOURCE</em>...</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Rename SOURCE to DEST, or move SOURCE(s) to DIRECTORY.</p><p>Mandatory arguments to long options are mandatory for short options too.</p><dl><dt><strong>--backup</strong>[=<em>CONTROL</em>]</dt><dd>make a backup of each existing destination file</dd><dt><strong>-b</strong></dt><dd>like <strong>--backup</strong> but does not accept an argument</dd><dt><strong>--debug</strong></dt><dd>explain how a file is copied. Implies <strong>-v</strong></dd><dt><strong>-f</strong>, <strong>--force</strong></dt><dd>do not prompt before overwriting</dd><dt><strong>-i</strong>, <strong>--interactive</strong></dt><dd>prompt before overwrite</dd><dt><strong>-n</strong>, <strong>--no-clobber</strong></dt><dd>do not overwrite an existing file</dd></dl><p>If you specify more than one of <strong>-i</strong>, <strong>-f</strong>, <strong>-n</strong>, only the final one takes effect.</p><dl><dt><strong>--no-copy</strong></dt><dd>do not copy if renaming fails</dd><dt><strong>--strip-trailing-slashes</strong></dt><dd>remove any trailing slashes from each SOURCE argument</dd><dt><strong>-S</strong>, <strong>--suffix</strong>=<em>SUFFIX</em></dt><dd>override the usual backup suffix</dd><dt><strong>-t</strong>, <strong>--target-directory</strong>=<em>DIRECTORY</em></dt><dd>move all SOURCE arguments into DIRECTORY</dd><dt><strong>-T</strong>, <strong>--no-target-directory</strong></dt><dd>treat DEST as a normal file</dd><dt><strong>--update</strong>[=<em>UPDATE</em>]</dt><dd>control which existing files are updated; UPDATE={all,none,older(default)}. See below</dd><dt><strong>-u</strong></dt><dd>equivalent to <strong>--update</strong>[=<em>older</em>]</dd><dt><strong>-v</strong>, <strong>--verbose</strong></dt><dd>explain what is being done</dd><dt><strong>-Z</strong>, <strong>--context</strong></dt><dd>set SELinux security context of destination file to default type</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>UPDATE controls which existing files in the destination are replaced. &#39;all&#39; is the default operation when an <strong>--update</strong> option is not specified, and results in all existing files in the destination being replaced. &#39;none&#39; is similar to the <strong>--no-clobber</strong> option, in that no files in the destination are replaced, but also skipped files do not induce a failure. &#39;older&#39; is the default operation when <strong>--update</strong> is specified, and results in files being replaced if they&#39;re older than the corresponding source file.</p><p>The backup suffix is &#39;~&#39;, unless set with <strong>--suffix</strong> or SIMPLE_BACKUP_SUFFIX. The version control method may be selected via the <strong>--backup</strong> option or through the VERSION_CONTROL environment variable. Here are the values:</p><dl><dt>none, off</dt><dd>never make backups (even if <strong>--backup</strong> is given)</dd><dt>numbered, t</dt><dd>make numbered backups</dd><dt>existing, nil</dt><dd>numbered if numbered backups exist, simple otherwise</dd><dt>simple, never</dt><dd>always make simple backups</dd></dl><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Mike Parker, David MacKenzie, and Jim Meyering.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>rename</strong>(2)</p><p><br> Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/mv%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/mv\\</a>&gt; <br> or available locally via: info &#39;(coreutils) mv invocation&#39;</p>',22);function g(e,m,p,c,h,u){return r(),o("div",null,[n("h1",i,a(e.$params.man),1),l])}const v=t(d,[["render",g]]);export{b as __pageData,v as default};
